class ReservaSerializer(serializers.ModelSerializer):
    class Meta:
        model = Reserva
        fields = ["id", "inicio", "fin", "personas"]

    def validate_personas(self, value):
        if value > 12:
            raise serializers.ValidationError("Máximo 12 personas por reserva.")
        return value

    def validate(self, attrs):
        if attrs["fin"] <= attrs["inicio"]:
            raise serializers.ValidationError({"fin": "Debe ser posterior al inicio."})
        return attrs

class ClienteMiniSerializer(serializers.ModelSerializer):
    class Meta:
        model = Cliente
        fields = ["id", "nombre"]


class PedidoSerializer(serializers.ModelSerializer):
    cliente = ClienteMiniSerializer(read_only=True)
    cliente_id = serializers.PrimaryKeyRelatedField(
        queryset=Cliente.objects.all(), source="cliente", write_only=True
    )
    total_con_iva = serializers.SerializerMethodField()

    class Meta:
        model = Pedido
        fields = ["id", "cliente", "cliente_id", "total", "total_con_iva"]

    def get_total_con_iva(self, obj):
        return round(obj.total * 119 / 100, 2)

